from datetime import date, timedelta
from typing import List, Optional, Dict, Set, Tuple

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = holidays if holidays is not None else []
        # Track used leave days per employee per year
        # Structure: {employee: {year: days_used}}
        self.used_days: Dict[str, Dict[int, int]] = {}
        # Track requests per employee
        # Structure: {employee: List[Tuple[date, date]]}
        self.requests: Dict[str, List[Tuple[date, date]]] = {}

    def _is_weekend(self, d: date) -> bool:
        """Check if a date is Saturday (5) or Sunday (6)"""
        return d.weekday() >= 5

    def _is_holiday(self, d: date) -> bool:
        """Check if a date is in the holidays list"""
        return d in self.holidays

    def _is_working_day(self, d: date) -> bool:
        """Check if a date is a working day (not weekend and not holiday)"""
        return not self._is_weekend(d) and not self._is_holiday(d)

    def _count_working_days(self, start: date, end: date) -> int:
        """Count working days between start and end (inclusive)"""
        count = 0
        current = start
        while current <= end:
            if self._is_working_day(current):
                count += 1
            current += timedelta(days=1)
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        # Requirement 1: end date before start date
        if end < start:
            raise ValueError("End date must be on or after start date")

        # Requirement 3: request made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days before start date")

        # Calculate working days in the requested period
        working_days = self._count_working_days(start, end)

        # Get the year for this request (use start year as the leave year)
        year = start.year

        # Get current used days for this employee and year
        if employee not in self.used_days:
            self.used_days[employee] = {}
        if year not in self.used_days[employee]:
            self.used_days[employee][year] = 0

        used_so_far = self.used_days[employee][year]

        # Requirement 2: check if enough days remaining
        remaining_days = self.days_per_year - used_so_far
        if working_days > remaining_days:
            raise ValueError("Not enough annual leave days remaining")

        # Record the used days
        self.used_days[employee][year] += working_days

        # Record the request
        if employee not in self.requests:
            self.requests[employee] = []
        self.requests[employee].append((start, end))

        return working_days

    def remaining(self, employee: str, year: int) -> int:
        """Return remaining leave days for the employee in the given year."""
        if employee not in self.used_days or year not in self.used_days[employee]:
            return self.days_per_year
        return self.days_per_year - self.used_days[employee][year]

    def employees(self) -> List[str]:
        """Return all employees with at least one request, sorted alphabetically."""
        return sorted(list(self.used_days.keys()))

    def requests_of(self, employee: str) -> List[Tuple[date, date]]:
        """Return the employee's requests as a list of (start_date, end_date) tuples."""
        if employee not in self.requests:
            return []
        return self.requests[employee].copy()
